"use client";

import type { AuthPageConfig, Testimonial } from "@/hooks/useAuthPageConfig";
import { Star } from "lucide-react";

// ── Avatar colors for the social proof stack ───────────────────────────
const AVATAR_COLORS = [
  "bg-indigo-500",
  "bg-violet-500",
  "bg-purple-400",
  "bg-violet-300",
  "bg-purple-600",
];

// ── Subcomponents ──────────────────────────────────────────────────────

function Logo() {
  return (
    <div className="flex items-center gap-2.5">
      <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-indigo-400 text-sm font-extrabold text-white">
        R
      </div>
      <span className="text-xl font-bold tracking-tight text-white">
        Rankora
      </span>
    </div>
  );
}

function AvatarStack({
  count,
  label,
}: {
  count: string;
  label: string;
}) {
  return (
    <div className="flex items-center">
      {AVATAR_COLORS.map((color, i) => (
        <div
          key={i}
          className={`flex h-9 w-9 items-center justify-center rounded-full border-2 border-white/20 text-[11px] font-semibold text-white ${color} ${i > 0 ? "-ml-2" : ""}`}
        >
          {["SC", "AK", "MR", "JP", "TL"][i]}
        </div>
      ))}
      <span className="ml-3 text-[13px] text-white/60">
        <strong className="text-white">{count}</strong> {label}
      </span>
    </div>
  );
}

function TestimonialCard({ testimonial }: { testimonial: Testimonial }) {
  return (
    <div className="rounded-[14px] border border-white/[0.07] bg-white/[0.05] p-5 backdrop-blur-sm">
      {/* Stars */}
      <div className="mb-2 flex gap-0.5">
        {Array.from({ length: testimonial.rating }).map((_, i) => (
          <Star
            key={i}
            className="h-3.5 w-3.5 fill-amber-400 text-amber-400"
          />
        ))}
      </div>

      {/* Quote */}
      <p className="mb-3.5 text-[14px] italic leading-relaxed text-white/75">
        &ldquo;{testimonial.quote}&rdquo;
      </p>

      {/* Author */}
      <div className="flex items-center gap-2.5">
        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-indigo-500 to-violet-400 text-xs font-bold text-white">
          {testimonial.avatar_initials}
        </div>
        <div>
          <div className="text-[13px] font-medium text-white/85">
            {testimonial.name}
          </div>
          <div className="text-[11px] text-white/40">
            {testimonial.role}, {testimonial.company}
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Main Panel ─────────────────────────────────────────────────────────

interface AuthLeftPanelProps {
  config: AuthPageConfig;
  variant: "signin" | "signup";
}

export function AuthLeftPanel({ config, variant }: AuthLeftPanelProps) {
  if (variant === "signup") {
    return <SignupLeftPanel config={config} />;
  }
  return <SigninLeftPanel config={config} />;
}

function SigninLeftPanel({ config }: { config: AuthPageConfig }) {
  const firstTestimonial = config.testimonials[0];

  return (
    <div className="relative flex w-full flex-col justify-between overflow-hidden bg-gradient-to-br from-[#1a1a2e] to-[#2d2b55] p-10 lg:p-12">
      {/* Floating glow effects */}
      <div className="pointer-events-none absolute -right-20 -top-[120px] h-80 w-80 rounded-full bg-[radial-gradient(circle,rgba(99,102,241,0.12)_0%,transparent_70%)] animate-auth-glow" />
      <div className="pointer-events-none absolute -bottom-[60px] -left-[60px] h-60 w-60 rounded-full bg-[radial-gradient(circle,rgba(129,140,248,0.08)_0%,transparent_70%)] animate-auth-glow-reverse" />

      {/* Logo */}
      <div className="relative z-10">
        <Logo />
      </div>

      {/* Hero text */}
      <div className="relative z-10">
        <h2 className="mb-3.5 whitespace-pre-line text-[30px] font-bold leading-tight text-white">
          {config.hero_headline}
        </h2>
        <p className="max-w-[360px] text-[15px] leading-relaxed text-white/55">
          {config.hero_description}
        </p>
      </div>

      {/* Social proof */}
      <div className="relative z-10 space-y-4">
        <AvatarStack
          count={config.social_proof_count}
          label={config.social_proof_label}
