  return (
    <div className="relative flex w-full flex-col justify-center overflow-hidden bg-gradient-to-br from-[#1a1a2e] to-[#2d2b55] p-10 lg:p-12">
      {/* Floating glow */}
      <div className="pointer-events-none absolute -right-[60px] -top-[100px] h-[280px] w-[280px] rounded-full bg-[radial-gradient(circle,rgba(99,102,241,0.12)_0%,transparent_70%)] animate-auth-glow" />

      <div className="relative z-10">
        <Logo />

        <h2 className="mb-6 mt-9 whitespace-pre-line text-[26px] font-bold leading-snug text-white">
          {config.signup_headline}
        </h2>

        {/* Benefits */}
        <div className="space-y-4">
          {config.signup_benefits.map((benefit, i) => (
            <div key={i} className="flex items-start gap-3">
              <div className="mt-0.5 flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full bg-indigo-500/20">
                <svg
                  className="h-3.5 w-3.5 text-indigo-300"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={3}
                >
                  <path d="m5 12 5 5L20 7" />
                </svg>
              </div>
              <p className="text-[14px] leading-relaxed text-white/70">
                <strong className="font-medium text-white">
                  {benefit.highlight}
                </strong>{" "}
                — {benefit.text}
              </p>
            </div>
