    --rk-accent: 220 14% 16%;
    --rk-accent-foreground: 220 14% 95%;

    --rk-destructive: 0 65% 65%;
    --rk-destructive-foreground: 0 0% 8%;

    --rk-success: 152 50% 55%;
    --rk-success-foreground: 0 0% 8%;

    --rk-warning: 36 70% 62%;
    --rk-warning-foreground: 0 0% 8%;

    --rk-border: 220 14% 18%;
    --rk-input: 220 14% 18%;
    --rk-ring: 217 91% 60%;

    --rk-score-overall: 217 91% 65%;
