@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-family: var(--font-inter), system-ui, -apple-system, sans-serif;
  }

  /* Global smooth transitions for interactive elements */
  button, a, input, textarea, select {
    @apply transition-colors duration-150;
  }
}

/* Disable ALL transitions during theme switch to prevent color fade/lag */
html.disable-transitions,
html.disable-transitions *,
html.disable-transitions *::before,
html.disable-transitions *::after {
  transition-duration: 0s !important;
  animation-duration: 0s !important;
}

