import type { Config } from "tailwindcss";

export default {
  darkMode: ["class"],
  content: ["./pages/**/*.{ts,tsx}", "./components/**/*.{ts,tsx}", "./app/**/*.{ts,tsx}", "./src/**/*.{ts,tsx}"],
  prefix: "",
  theme: {
    container: {
      center: true,
      padding: "2rem",
      screens: {
        "2xl": "1400px",
      },
    },
    extend: {
      colors: {
        border: "hsl(var(--rk-border))",
        input: "hsl(var(--rk-input))",
        ring: "hsl(var(--rk-ring))",
        background: "hsl(var(--rk-background))",
        foreground: "hsl(var(--rk-foreground))",
        primary: {
          DEFAULT: "hsl(var(--rk-primary))",
          foreground: "hsl(var(--rk-primary-foreground))",
        },
        secondary: {
          DEFAULT: "hsl(var(--rk-secondary))",
          foreground: "hsl(var(--rk-secondary-foreground))",
        },
        destructive: {
          DEFAULT: "hsl(var(--rk-destructive))",
          foreground: "hsl(var(--rk-destructive-foreground))",
        },
        muted: {
          DEFAULT: "hsl(var(--rk-muted))",
          foreground: "hsl(var(--rk-muted-foreground))",
        },
        accent: {
          DEFAULT: "hsl(var(--rk-accent))",
          foreground: "hsl(var(--rk-accent-foreground))",
        },
        popover: {
          DEFAULT: "hsl(var(--rk-popover))",
          foreground: "hsl(var(--rk-popover-foreground))",
        },
        card: {
          DEFAULT: "hsl(var(--rk-card))",
          foreground: "hsl(var(--rk-card-foreground))",
        },
        success: {
          DEFAULT: "hsl(var(--rk-success))",
          foreground: "hsl(var(--rk-success-foreground))",
        },
        warning: {
          DEFAULT: "hsl(var(--rk-warning))",
          foreground: "hsl(var(--rk-warning-foreground))",
        },
        score: {
          overall: "hsl(var(--rk-score-overall))",
          skills: "hsl(var(--rk-score-skills))",
          education: "hsl(var(--rk-score-education))",
          jd: "hsl(var(--rk-score-jd))",
        },
        sidebar: {
          DEFAULT: "hsl(var(--rk-sidebar-background))",
          foreground: "hsl(var(--rk-sidebar-foreground))",
          primary: "hsl(var(--rk-sidebar-primary))",
          "primary-foreground": "hsl(var(--rk-sidebar-primary-foreground))",
          accent: "hsl(var(--rk-sidebar-accent))",
          "accent-foreground": "hsl(var(--rk-sidebar-accent-foreground))",
          border: "hsl(var(--rk-sidebar-border))",
          ring: "hsl(var(--rk-sidebar-ring))",
        },
      },
      borderRadius: {
        lg: "var(--radius)",
        md: "calc(var(--radius) - 2px)",
        sm: "calc(var(--radius) - 4px)",
      },
      keyframes: {
        "accordion-down": {
          from: { height: "0" },
          to: { height: "var(--radix-accordion-content-height)" },
        },
        "accordion-up": {
          from: { height: "var(--radix-accordion-content-height)" },
          to: { height: "0" },
        },
        float: {
          "0%, 100%": { transform: "translateY(0px)" },
          "50%": { transform: "translateY(-8px)" },
        },
        "auth-glow": {
          "0%, 100%": { transform: "translate(0, 0) scale(1)" },
          "50%": { transform: "translate(10px, -10px) scale(1.05)" },
        },
        "auth-glow-reverse": {
          "0%, 100%": { transform: "translate(0, 0) scale(1)" },
          "50%": { transform: "translate(-10px, 10px) scale(1.05)" },
        },
      },
      animation: {
        "accordion-down": "accordion-down 0.2s ease-out",
        "accordion-up": "accordion-up 0.2s ease-out",
        float: "float 4s ease-in-out infinite",
        "auth-glow": "auth-glow 8s ease-in-out infinite",
        "auth-glow-reverse": "auth-glow-reverse 6s ease-in-out infinite",
      },
    },
  },
