"use client";

import type { AuthPageConfig, Testimonial } from "@/hooks/useAuthPageConfig";
import { Star } from "lucide-react";

const AVATAR_COLORS = [
  "bg-auth-accent",
  "bg-violet-500",
  "bg-purple-400",
  "bg-violet-300",
  "bg-purple-600",
] as const;

const AVATAR_INITIALS = ["SC", "AK", "MR", "JP", "TL"] as const;

function Logo() {
  return (
    <div className="flex items-center gap-2.5">
      <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-auth-accent to-auth-accent/80 text-sm font-extrabold text-white">
        R
      </div>
      <span className="text-xl font-bold tracking-tight text-white">
        Rankora
      </span>
    </div>
  );
}

function AvatarStack({ count, label }: { count: string; label: string }) {
  return (
    <div className="flex items-center" role="group" aria-label={`${count} ${label}`}>
      {AVATAR_COLORS.map((color, i) => (
        <div
          key={i}
          aria-hidden="true"
          className={`flex h-9 w-9 items-center justify-center rounded-full border-2 border-white/20 text-xs font-semibold text-white ${color} ${i > 0 ? "-ml-2" : ""}`}
        >
          {AVATAR_INITIALS[i]}
        </div>
      ))}
      <span className="ml-3 text-xs text-white/60">
        <strong className="text-white">{count}</strong> {label}
      </span>
    </div>
  );
}

function TestimonialCard({ testimonial }: { testimonial: Testimonial }) {
  return (
    <figure className="rounded-xl border border-white/[0.07] bg-white/[0.05] p-5 backdrop-blur-sm">
      <div className="mb-2 flex gap-0.5" aria-label={`${testimonial.rating} out of 5 stars`}>
        {Array.from({ length: testimonial.rating }).map((_, i) => (
          <Star
            key={i}
