"use client";

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";

interface SocialAuthButtonsProps {
  googleEnabled: boolean;
  microsoftEnabled: boolean;
  mode: "signin" | "signup";
  disabled?: boolean;
}

export function SocialAuthButtons({
  googleEnabled,
  microsoftEnabled,
  mode,
  disabled,
}: SocialAuthButtonsProps) {
  const [loadingProvider, setLoadingProvider] = useState<string | null>(null);

  const handleOAuth = async (provider: "google" | "azure") => {
    setLoadingProvider(provider);
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider,
        options: {
          redirectTo: `${window.location.origin}/auth`,
          queryParams:
            provider === "azure"
              ? { prompt: "select_account" }
              : undefined,
        },
      });
      if (error) {
        toast.error(error.message);
        setLoadingProvider(null);
      }
    } catch {
      toast.error("Failed to start authentication. Please try again.");
      setLoadingProvider(null);
    }
  };

  if (!googleEnabled && !microsoftEnabled) return null;

  const label = mode === "signup" ? "Sign up with" : "Continue with";
  const isDisabled = disabled || loadingProvider !== null;

  return (
    <div className="flex gap-2.5">
      {googleEnabled && (
        <button
          type="button"
          onClick={() => handleOAuth("google")}
          disabled={isDisabled}
          aria-label={`${label} Google`}
          className="flex flex-1 items-center justify-center gap-2.5 rounded-lg border border-border bg-background px-4 py-3 text-sm font-medium text-foreground transition-all hover:-translate-y-px hover:border-border/80 hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0 disabled:pointer-events-none disabled:opacity-50"
        >
          {loadingProvider === "google" ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <GoogleIcon />
          )}
          {googleEnabled && !microsoftEnabled ? `${label} Google` : "Google"}
        </button>
      )}

      {microsoftEnabled && (
        <button
          type="button"
          onClick={() => handleOAuth("azure")}
          disabled={isDisabled}
          aria-label={`${label} Microsoft`}
          className="flex flex-1 items-center justify-center gap-2.5 rounded-lg border border-border bg-background px-4 py-3 text-sm font-medium text-foreground transition-all hover:-translate-y-px hover:border-border/80 hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0 disabled:pointer-events-none disabled:opacity-50"
        >
          {loadingProvider === "azure" ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <MicrosoftIcon />
          )}
          {microsoftEnabled && !googleEnabled
            ? `${label} Microsoft`
            : "Microsoft"}
        </button>
      )}
    </div>
  );
}

function GoogleIcon() {
  return (
    <svg aria-hidden="true" className="h-[18px] w-[18px] flex-shrink-0" viewBox="0 0 24 24">
      <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4" />
      <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
      <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
      <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
    </svg>
  );
}

function MicrosoftIcon() {
