          microsoftEnabled={config.microsoft_auth_enabled}
          mode="signin"
          disabled={loading}
        />

        {(config.google_auth_enabled || config.microsoft_auth_enabled) && (
          <div className="my-5">
            <Divider />
          </div>
        )}

        {/* Email / Password form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label
