"use client";

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";
import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
import { SocialAuthButtons } from "./SocialAuthButtons";
import { Divider } from "./Divider";
import { TrustBadges } from "./TrustBadges";

interface SignUpFormProps {
  config: AuthPageConfig;
  onSuccess?: () => void;
  onSwitchToSignIn: () => void;
}

type Step = 1 | 2 | 3;

const STEP_LABELS: Record<Step, string> = {
  1: "just your email to start",
  2: "what should we call you?",
  3: "set a secure password",
};

export function SignUpForm({
  config,
  onSuccess,
  onSwitchToSignIn,
}: SignUpFormProps) {
  const [step, setStep] = useState<Step>(1);
  const [email, setEmail] = useState("");
  const [fullName, setFullName] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);

  const passwordMismatch = !!confirmPassword && password !== confirmPassword;

  const handleStep1 = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;
    setStep(2);
  };

  const handleStep2 = (e: React.FormEvent) => {
    e.preventDefault();
    if (!fullName) return;
    setStep(3);
  };

  const handleStep3 = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordMismatch) {
      toast.error("Passwords do not match");
      return;
    }
    if (password.length < 6) {
      toast.error("Password must be at least 6 characters");
      return;
    }

    setLoading(true);
    try {
      const { error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          emailRedirectTo: window.location.origin,
          data: { full_name: fullName },
        },
      });
      if (error) {
        toast.error(error.message);
      } else {
        toast.success("Check your email to confirm your account!");
        onSuccess?.();
      }
    } catch {
      toast.error("An unexpected error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const hasSso = config.google_auth_enabled || config.microsoft_auth_enabled;

  return (
    <div className="flex w-full flex-col justify-center bg-background px-6 py-10 sm:px-10 lg:px-14">
      <div className="mx-auto w-full max-w-[400px]">
        {/* Mobile logo */}
        <div className="mb-8 flex items-center gap-2.5 md:hidden">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-auth-accent to-auth-accent/80 text-sm font-extrabold text-white">
            R
          </div>
          <span className="text-xl font-bold tracking-tight text-foreground">
            Rankora
          </span>
        </div>

        {/* Step indicator */}
        <div
          className="mb-6 flex items-center gap-2"
          role="progressbar"
          aria-valuenow={step}
          aria-valuemin={1}
          aria-valuemax={3}
          aria-label={`Step ${step} of 3`}
        >
          {([1, 2, 3] as const).map((s) => (
            <div
              key={s}
              className={`h-2 rounded-full transition-all duration-300 ${
                s === step
                  ? "w-6 bg-auth-accent"
                  : s < step
                    ? "w-2 bg-success"
                    : "w-2 bg-border"
              }`}
            />
          ))}
        </div>

        {/* Header */}
        <div className="mb-7">
          <h1 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl">
            {config.signup_heading}
          </h1>
          <p className="mt-1.5 text-sm text-muted-foreground">
            Step {step} of 3 — {STEP_LABELS[step]}
          </p>
        </div>

        {/* Step 1: Email only */}
        {step === 1 && (
          <>
            <SocialAuthButtons
              googleEnabled={config.google_auth_enabled}
              microsoftEnabled={config.microsoft_auth_enabled}
              mode="signup"
              disabled={loading}
            />

            {hasSso && (
              <div className="my-5">
                <Divider />
              </div>
            )}

            <form onSubmit={handleStep1} className="space-y-4">
              <div className="space-y-1.5">
                <label
                  htmlFor="signup-email"
                  className="text-sm font-medium text-foreground"
                >
                  Work email
                </label>
                <Input
                  id="signup-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="name@company.com"
                  autoComplete="email"
                  autoFocus
                  required
                  className="h-11 rounded-lg"
                />
              </div>

              <button
                type="submit"
                className="flex w-full items-center justify-center rounded-lg bg-auth-accent px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-accent-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0"
              >
                Continue <span aria-hidden="true">&rarr;</span>
              </button>
            </form>
          </>
        )}

        {/* Step 2: Full name */}
        {step === 2 && (
          <form onSubmit={handleStep2} className="space-y-4">
            <div className="space-y-1.5">
              <label
                htmlFor="signup-name"
                className="text-sm font-medium text-foreground"
              >
                Full name
              </label>
              <Input
                id="signup-name"
                type="text"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                placeholder="Jane Smith"
                autoComplete="name"
                autoFocus
                required
                className="h-11 rounded-lg"
              />
            </div>

            <div className="flex gap-3">
              <button
                type="button"
                onClick={() => setStep(1)}
                className="flex-1 rounded-lg border border-border px-4 py-3 text-sm font-medium text-foreground transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              >
                Back
              </button>
              <button
                type="submit"
                className="flex flex-[2] items-center justify-center rounded-lg bg-auth-accent px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-accent-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0"
              >
                Continue <span aria-hidden="true">&rarr;</span>
              </button>
            </div>
          </form>
        )}

        {/* Step 3: Password */}
        {step === 3 && (
          <form onSubmit={handleStep3} className="space-y-4">
            <div className="space-y-1.5">
              <label
                htmlFor="signup-password"
                className="text-sm font-medium text-foreground"
              >
                Password
              </label>
              <Input
                id="signup-password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Min 6 characters"
                autoComplete="new-password"
                autoFocus
                required
                disabled={loading}
                minLength={6}
                className="h-11 rounded-lg"
              />
              <p className="text-xs text-muted-foreground">
                At least 6 characters required
              </p>
            </div>

            <div className="space-y-1.5">
              <label
                htmlFor="signup-confirm-password"
                className="text-sm font-medium text-foreground"
              >
                Confirm password
              </label>
              <Input
                id="signup-confirm-password"
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Repeat password"
                autoComplete="new-password"
                required
                disabled={loading}
                minLength={6}
                aria-invalid={passwordMismatch}
                aria-describedby={
                  passwordMismatch ? "password-mismatch-error" : undefined
                }
                className={`h-11 rounded-lg ${passwordMismatch ? "border-destructive focus-visible:ring-destructive" : ""}`}
              />
              {passwordMismatch && (
                <p
                  id="password-mismatch-error"
                  className="text-xs text-destructive"
                  role="alert"
                >
                  Passwords do not match
                </p>
              )}
            </div>

            <div className="flex gap-3">
              <button
                type="button"
                onClick={() => setStep(2)}
                className="flex-1 rounded-lg border border-border px-4 py-3 text-sm font-medium text-foreground transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              >
                Back
              </button>
              <button
                type="submit"
                disabled={loading || passwordMismatch}
                className="flex flex-[2] items-center justify-center rounded-lg bg-auth-btn px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-btn-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0 disabled:pointer-events-none disabled:opacity-50"
              >
                {loading && (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                )}
                Create account
              </button>
            </div>
          </form>
        )}

        {/* Switch to signin */}
        <p className="mt-5 text-center text-sm text-muted-foreground">
          Already have an account?{" "}
          <button
            type="button"
            onClick={onSwitchToSignIn}
            className="font-semibold text-auth-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-sm"
          >
            Sign in
          </button>
        </p>

        {/* Trust badges */}
        <div className="mt-6">
          <TrustBadges
            badges={[
              { icon: "lock", label: "No credit card needed" },
              { icon: "shield", label: "Free trial" },
            ]}
          />
        </div>
      </div>
    </div>
  );
}

