                className="h-11 rounded-lg"
              />
              <p className="text-xs text-muted-foreground">
                At least 6 characters required
              </p>
            </div>

            <div className="space-y-1.5">
              <label
                htmlFor="signup-confirm-password"
                className="text-sm font-medium text-foreground"
              >
                Confirm password
              </label>
              <Input
                id="signup-confirm-password"
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Repeat password"
                autoComplete="new-password"
                required
                disabled={loading}
                minLength={6}
                aria-invalid={passwordMismatch}
                aria-describedby={
                  passwordMismatch ? "password-mismatch-error" : undefined
                }
                className={`h-11 rounded-lg ${passwordMismatch ? "border-destructive focus-visible:ring-destructive" : ""}`}
              />
              {passwordMismatch && (
                <p
                  id="password-mismatch-error"
                  className="text-xs text-destructive"
                  role="alert"
                >
                  Passwords do not match
                </p>
              )}
            </div>

            <div className="flex gap-3">
              <button
                type="button"
                onClick={() => setStep(2)}
                className="flex-1 rounded-lg border border-border px-4 py-3 text-sm font-medium text-foreground transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              >
                Back
              </button>
              <button
                type="submit"
                disabled={loading || passwordMismatch}
                className="flex flex-[2] items-center justify-center rounded-lg bg-auth-btn px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-btn-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0 disabled:pointer-events-none disabled:opacity-50"
              >
                {loading && (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                )}
                Create account
              </button>
            </div>
          </form>
        )}

        {/* Switch to signin */}
        <p className="mt-5 text-center text-sm text-muted-foreground">
          Already have an account?{" "}
          <button
            type="button"
            onClick={onSwitchToSignIn}
            className="font-semibold text-auth-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-sm"
          >
            Sign in
          </button>
        </p>

        {/* Trust badges */}
        <div className="mt-6">
          <TrustBadges
            badges={[
              { icon: "lock", label: "No credit card needed" },
              { icon: "shield", label: "Free trial" },
            ]}
          />
        </div>
      </div>
    </div>
  );
}

