    },
    {
      highlight: "Team collaboration",
      text: "invite your hiring team and start working together",
    },
    {
      highlight: "Cancel anytime",
      text: "no lock-in, no hidden fees, ever",
    },
  ],
  signup_headline: "Start hiring smarter\nin under 2 minutes",
  signup_social_proof_count: "2,400+",
  signup_social_proof_label: "recruiters signed up this month",
