  microsoft_auth_enabled: true,
  magic_link_enabled: true,
  signin_heading: "Welcome back",
  signin_subheading: "Sign in to continue to your dashboard",
  signup_heading: "Create your account",
  signup_subheading: "Just your email to start",
};

// ── Raw DB row shape (not in auto-generated types until migration runs) ──

interface AuthPageConfigRow {
  hero_headline: string | null;
  hero_description: string | null;
  logo_url: string | null;
  social_proof_count: string | null;
  social_proof_label: string | null;
  testimonials_json: Testimonial[] | null;
  trust_badges_json: TrustBadge[] | null;
  signup_benefits_json: SignupBenefit[] | null;
  signup_headline: string | null;
  signup_social_proof_count: string | null;
  signup_social_proof_label: string | null;
  google_auth_enabled: boolean | null;
  microsoft_auth_enabled: boolean | null;
  magic_link_enabled: boolean | null;
  signin_heading: string | null;
  signin_subheading: string | null;
  signup_heading: string | null;
  signup_subheading: string | null;
}

// ── Fetcher ────────────────────────────────────────────────────────────

async function fetchAuthPageConfig(): Promise<AuthPageConfig> {
  try {
    // Use the REST API directly to avoid type-generation dependency.
    // The table has public SELECT via RLS so anon key works.
    const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
    if (!url || !key) return DEFAULTS;

    const res = await fetch(
      `${url}/rest/v1/auth_page_config?select=*&limit=1`,
      {
        headers: {
          apikey: key,
          Authorization: `Bearer ${key}`,
          Accept: "application/json",
        },
      },
    );

    if (!res.ok) return DEFAULTS;

    const rows: AuthPageConfigRow[] = await res.json();
    const data = rows[0];
    if (!data) return DEFAULTS;

    return {
      hero_headline: data.hero_headline ?? DEFAULTS.hero_headline,
      hero_description: data.hero_description ?? DEFAULTS.hero_description,
      logo_url: data.logo_url ?? null,
      social_proof_count:
        data.social_proof_count ?? DEFAULTS.social_proof_count,
      social_proof_label:
        data.social_proof_label ?? DEFAULTS.social_proof_label,
      testimonials: Array.isArray(data.testimonials_json)
        ? data.testimonials_json
        : DEFAULTS.testimonials,
      trust_badges: Array.isArray(data.trust_badges_json)
        ? data.trust_badges_json
        : DEFAULTS.trust_badges,
      signup_benefits: Array.isArray(data.signup_benefits_json)
        ? data.signup_benefits_json
        : DEFAULTS.signup_benefits,
      signup_headline: data.signup_headline ?? DEFAULTS.signup_headline,
      signup_social_proof_count:
        data.signup_social_proof_count ?? DEFAULTS.signup_social_proof_count,
      signup_social_proof_label:
        data.signup_social_proof_label ?? DEFAULTS.signup_social_proof_label,
      google_auth_enabled: data.google_auth_enabled ?? true,
      microsoft_auth_enabled: data.microsoft_auth_enabled ?? true,
      magic_link_enabled: data.magic_link_enabled ?? true,
      signin_heading: data.signin_heading ?? DEFAULTS.signin_heading,
      signin_subheading: data.signin_subheading ?? DEFAULTS.signin_subheading,
      signup_heading: data.signup_heading ?? DEFAULTS.signup_heading,
      signup_subheading: data.signup_subheading ?? DEFAULTS.signup_subheading,
    };
  } catch {
    // Table may not exist yet — fall back to defaults
    return DEFAULTS;
  }
}

// ── Hook ───────────────────────────────────────────────────────────────

export function useAuthPageConfig() {
  const { data, isLoading } = useQuery({
    queryKey: ["auth-page-config"],
    queryFn: fetchAuthPageConfig,
    staleTime: 5 * 60 * 1000, // 5 minutes
    gcTime: 30 * 60 * 1000, // 30 minutes
    retry: 1,
  });

  return {
    config: data ?? DEFAULTS,
    isLoading,
  };
}

