"use client";

import { useState, useEffect, createContext, useContext, useRef } from "react";
import { supabase } from "@/integrations/supabase/browser";
import type { User, Session } from "@supabase/supabase-js";

type Profile = {
  credits: number;
  subscription_credits: number;
  topup_credits: number;
  bonus_credits: number;
  inbox_email: string | null;
  plan: string;
  email_enabled: boolean;
  auto_rank_enabled: boolean;
  subscription_ends_at: string | null;
};

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  isAdmin: boolean;
  profile: Profile | null;
  /**
   * Non-null when either the profile or role fetch failed. Consumers
   * can surface a toast/banner; the rest of the app still renders.
   */
  authError: string | null;
  signOut: () => Promise<void>;
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  session: null,
  loading: true,
  isAdmin: false,
  profile: null,
  authError: null,
  signOut: async () => {},
  refreshProfile: async () => {},
});

// eslint-disable-next-line react-refresh/only-export-components
export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const userIdRef = useRef<string | null>(null);

  const fetchProfile = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from("profiles")
        .select(
          "credits, subscription_credits, topup_credits, bonus_credits, inbox_email, plan, email_enabled, auto_rank_enabled, subscription_ends_at",
        )
        .eq("user_id", userId)
        .single();
      if (error) throw error;
      if (data) {
        setProfile(data as Profile);
        setAuthError(null);
      }
    } catch (err) {
      console.error("[useAuth] Error fetching profile:", err);
      setAuthError(
        err instanceof Error
          ? `Could not load profile: ${err.message}`
          : "Could not load profile",
      );
    }
  };

  const fetchRole = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from("user_roles")
        .select("role")
        .eq("user_id", userId);
      if (error) throw error;
      setIsAdmin(
        (data ?? []).some((r: { role: string }) => r.role === "admin"),
      );
    } catch (err) {
      console.error("[useAuth] Error fetching role:", err);
      // Role fetch failures should NOT silently leave isAdmin=false from
      // a previous session — reset it and surface the error so the admin
      // panel redirect doesn't look like a bug to the user.
      setIsAdmin(false);
      setAuthError(
        err instanceof Error
          ? `Could not verify permissions: ${err.message}`
          : "Could not verify permissions",
      );
    }
  };

  const refreshProfile = async () => {
    if (userIdRef.current) await fetchProfile(userIdRef.current);
  };

  useEffect(() => {
    // Single source of truth: onAuthStateChange fires an INITIAL_SESSION
    // event on subscribe, which gives us the current session without a
    // separate getSession() call. This eliminates the race where
    // getSession() could resolve with null before onAuthStateChange
    // caught up, briefly wiping a known-good user state.
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (_event, nextSession) => {
      setSession(nextSession);
      setUser(nextSession?.user ?? null);
      userIdRef.current = nextSession?.user?.id ?? null;

      if (nextSession?.user) {
        // setTimeout avoids the Supabase deadlock inside onAuthStateChange
        setTimeout(async () => {
          await Promise.all([
            fetchProfile(nextSession.user.id),
            fetchRole(nextSession.user.id),
          ]);
        }, 0);
      } else {
        setProfile(null);
        setIsAdmin(false);
        setAuthError(null);
      }
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Refresh profile on window focus + every 2min to keep credits current
  useEffect(() => {
    if (!user) return;
    const handleFocus = () => fetchProfile(user.id);
    window.addEventListener("focus", handleFocus);
    const interval = setInterval(() => fetchProfile(user.id), 120_000);
    return () => {
      window.removeEventListener("focus", handleFocus);
      clearInterval(interval);
    };
    // Intentional: re-run only on user identity change (id), not on every
    // Supabase user object reference change. fetchProfile is stable because
    // it closes over `supabase` which is a module singleton.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  const signOut = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setSession(null);
    setProfile(null);
    setIsAdmin(false);
    setAuthError(null);
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        session,
        loading,
        isAdmin,
        profile,
        authError,
        signOut,
        refreshProfile,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

