import type { Metadata, Viewport } from "next";
import Script from "next/script";
import { Inter } from "next/font/google";
import { Providers } from "./providers";
import "./globals.css";

// next/font self-hosts the font files and eliminates the render-blocking
// Google Fonts @import we used to ship via src/index.css. Exposes as a
// CSS variable so the body rule in src/index.css can reference it.
const inter = Inter({
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  display: "swap",
  variable: "--font-inter",
});

const APP_URL =
  process.env.NEXT_PUBLIC_APP_URL?.replace(/\/$/, "") ||
  "https://rankora.co";
const OG_IMAGE =
  "https://pub-bb2e103a32db4e198524a2e9ed8f35b4.r2.dev/8866adbf-82a9-49f0-b833-0aa54e4b006a/id-preview-d52e7914--a9db58a3-cf4a-466e-9c81-889096bf5024.lovable.app-1771166124703.png";

export const metadata: Metadata = {
  metadataBase: new URL(APP_URL),
  title: {
    default: "Rankora - AI-Powered Resume Screening",
    template: "%s · Rankora",
  },
  description:
    "Screen and rank resumes in seconds using GPT-4o. Paste a job description, upload resumes, and get AI-powered candidate rankings instantly.",
  keywords: [
    "resume ranker",
    "AI resume screening",
    "resume scoring",
    "hiring tool",
    "recruitment automation",
    "ATS",
    "applicant tracking",
  ],
  authors: [{ name: "Rankora" }],
  creator: "Rankora",
  robots: {
    index: true,
    follow: true,
    googleBot: { index: true, follow: true, "max-image-preview": "large" },
  },
  icons: {
    // Only declare files that actually exist in public/. Adding
    // references to missing icons causes 404s in the Network panel
    // and hurts Lighthouse PWA score.
    icon: [{ url: "/favicon.ico", sizes: "any" }],
  },
  openGraph: {
    type: "website",
    url: APP_URL,
    title: "Rankora - AI-Powered Resume Screening",
    description:
      "Screen and rank resumes in seconds using GPT-4o. Paste a job description, upload resumes, and get AI-powered candidate rankings instantly.",
    siteName: "Rankora",
    images: [{ url: OG_IMAGE, width: 1200, height: 630, alt: "Rankora" }],
  },
  twitter: {
    card: "summary_large_image",
    title: "Rankora - AI-Powered Resume Screening",
    description:
      "Screen and rank resumes in seconds using GPT-4o. Paste a job description, upload resumes, and get AI-powered candidate rankings instantly.",
    images: [OG_IMAGE],
  },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: "#8b5cf6",
};

const themeInitScript = `(function() {
  var theme = localStorage.getItem('rankora-theme');
  if (theme === 'dark') {
    document.documentElement.classList.add('dark');
    document.documentElement.style.colorScheme = 'dark';
  }
})();`;

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  // Root layout is intentionally synchronous and has no cookies/auth
  // reads, so every route inherits static-render eligibility. Pages
  // that need the server-side user (e.g. app/page.tsx for landing vs
  // dashboard, or app/(protected)/**/page.tsx for requireUser guards)
  // fetch it themselves via app/_lib/server-auth helpers.
  return (
    <html
      lang="en"
      className={inter.variable}
      suppressHydrationWarning
    >
      <head>
        <Script
          id="theme-init"
          strategy="beforeInteractive"
          dangerouslySetInnerHTML={{ __html: themeInitScript }}
        />
      </head>
      <body>
        <Providers>{children}</Providers>
      </body>
    </html>
  );
}

